select cf.company_id, cc.name, p.end_date, cf.value from analytics.canonical_fact cf join analytics.canonical_concept cc on cc.id=cf.canonical_concept_id join core.period p on p.id=cf.period_id where cf.company_id in (1168) and cc.name in ('total_debt','total_debt_resolved') and p.end_date>='2025-06-30' order by 2,3;
select f.company_id, co.tag, p.end_date, f.value, f.is_authoritative from core.fact f join core.concept co on co.id=f.concept_id join core.period p on p.id=f.period_id where f.company_id=1553 and co.tag in ('LongTermDebt','DebtCurrent','LongTermDebtNoncurrent') and p.end_date>='2024-12-31' order by p.end_date, co.tag limit 20
